import {CARD_CATALOG,CARD_MAP,STAGES,CARD_KINDS,RARITY_ODDS} from './catalog.js';
import {upgradeCost,craftCost,itemPower,eventPower,eventDescription} from './rules.js';
import {cardClient} from './client.js';
const root=document.querySelector('#app');
let state=null,tab='draw',filter='all',ownedOnly=false,selected=null,reveal=null,busy=false,error='',notice='',actor=0,deckDraft=null;
const effectText=card=>card.kind==='event'?eventDescription(card,state?.collection?.[card.id]?.level||1):card.description;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=24)=>{const paths={spark:'M12 2l2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',cards:'M6 3h12v18H6zM3 6v12M21 6v12M9 8h6M9 12h6M9 16h3',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z',sword:'m4 20 4-4m-4-4 8 8M8 16 20 4v6L10 20M14 4h6',heart:'M12 20S2 14 2 8c0-6 8-6 10 0 2-6 10-6 10 0 0 6-10 12-10 12',arrow:'M4 12h16m-6-6 6 6-6 6',ticket:'M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4zM9 6v12',gem:'m12 2 9 8-9 12L3 10zm-9 8h18M8 4l4 18 4-18',flag:'M5 22V3h13l-3 4 3 4H5',clock:'M12 8v5l3 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',check:'m4 12 5 5L20 6',close:'m5 5 14 14M19 5 5 19'};return`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;};
function art(card){if(card.portrait)return`<img src="${card.portrait}" alt="${esc(card.name)}的動畫角色" loading="lazy">`;const glyph={heal:'heart',shield:'shield',damage:'sword',pressure:'sword',focus:'spark',charge:'spark',expose:'cards',drain:'clock',weaken:'clock'}[card.effect];return`<div class="object-art effect-${card.effect}"><i></i>${icon(glyph,76)}<span>${card.kind==='item'?'OFFICE RELIC':'OFFICE INCIDENT'}</span></div>`;}
function cardView(card,{small=false,selectable=true,drawn=null}={}){const entry=state?.collection?.[card.id],locked=state&&!entry;return`<${selectable?'button':'div'} ${selectable?`type="button" data-inspect="${card.id}"`:''} class="game-card rarity-${card.rarity} ${small?'small':''} ${locked?'unowned':''}"><div class="card-top"><span>${card.rarity}</span><span>${CARD_KINDS[card.kind]}${entry?` · Lv.${entry.level}`:''}</span></div><div class="card-art">${art(card)}</div><div class="card-caption"><strong>${esc(card.name)}</strong><span>${esc(card.skill||effectText(card))}</span></div>${drawn?`<b class="draw-tag">${drawn.duplicate?`重複 · +${drawn.shards} 碎片`:'NEW'}</b>`:''}</${selectable?'button':'div'}>`;}
function shell(content){const count=state?Object.keys(state.collection).length:0;return`<header class="site-header"><a href="/cards/" class="brand"><span class="brand-mark">${icon('cards',22)}</span><span>移動<span class="brand-sub">抽卡遊戲</span></span></a><nav aria-label="其他入口"><a href="/">移動人生 ${icon('arrow',15)}</a><a href="https://bvivify.com/" target="_blank" rel="noopener">BviviFy ↗</a></nav></header><main>${state?`<div class="account-bar"><span class="connection ${cardClient.mode==='practice'?'practice':''}">${cardClient.mode==='practice'?'本機練習卡冊 · 與正式收藏分開':cardClient.hasPending?'操作待確認 · 請重新連線':'匿名卡冊 · 已連線'}</span><div class="wallet"><span>${icon('ticket',17)}<b>${state.tickets}</b> 抽卡券</span><span>${icon('gem',17)}<b>${state.shards}</b> 碎片</span><span class="card-count">${count} / ${CARD_CATALOG.length} 收藏</span></div><button class="text-button" data-connect ${busy?'disabled':''}>重新連線</button></div><div class="tabbar" role="tablist" aria-label="卡牌遊戲功能">${[['draw','spark','抽卡'],['deck','cards','編成'],['campaign','flag','辦公室挑戰'],['collection','gem','收藏冊']].map(([id,glyph,label])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''}">${icon(glyph,19)}${label}</button>`).join('')}</div>`:''}${error?`<div class="message error" role="alert">${esc(error)} ${!state?'<button data-practice>先用本機練習卡冊</button>':''}</div>`:''}${notice?`<div class="message" role="status">${esc(notice)}</div>`:''}${content}</main><footer><span>最後一抽，真的。<small>原創職場卡牌遊戲 · 人物與劇情為虛構改編</small></span><p>免費遊玩，沒有現金儲值或交易。卡冊沿用這個瀏覽器的匿名身分；清除瀏覽器資料或換裝置，可能無法取回。<a href="/">回到移動人生 ↗</a></p></footer>${busy?'<div class="busy-bar" role="status">正在確認卡冊…</div>':''}${selected?detailModal(CARD_MAP[selected]):''}${reveal?revealModal():''}`;}
function intro(){return`<section class="intro hero"><div class="hero-copy"><div class="eyebrow">THE MOVING DECK / 01</div><h1>人生很難抽中好籤。<br><em>至少這裡，二十抽保底。</em></h1><p>把移動人生的結算積分換成抽卡券。收集人物、物品與事件，組成三人小隊，回辦公室打一場有附件的攻防戰。</p><div class="hero-actions"><button class="primary" data-connect ${busy?'disabled':''}>打開我的卡冊 ${icon('arrow',20)}</button><a href="/">先去上班賺抽卡券 ↗</a></div><div class="starter-note">第一次開冊：15 張券＋9 張起始卡。不花錢也能一路玩。</div></div><div class="alice-stage"><div class="halo"></div><span class="floating-label">SSR / 愛麗絲</span><img src="/assets/alice.png" alt="拿著手機的愛麗絲動畫角色"><div class="speech">「我沒有課金。<br>我只是把人生換成卡片。」</div><span class="stage-caption">ALICE · 最後一抽推廣大使</span></div></section><section class="how-grid"><article><span>01 / COLLECT</span><h2>抽到辦公室熟面孔。</h2><p>29 位人物、18 件物品、18 段事件。單抽與十連共用保底，抽到重複卡會變成可用的碎片。</p></article><article><span>02 / BUILD</span><h2>不是稀有就一定好用。</h2><p>三位人物、一件物品、一張事件卡。護盾、補血、破防與爆發，要留給對的回合。</p></article><article><span>03 / CHALLENGE</span><h2>十關，願景逐漸升級。</h2><p>每三回合都有重攻勢。先看對手意圖，再決定出手、掩護或開技能。首勝可以再拿券。</p></article></section>`;}
function drawPage(){return`<section class="draw-layout"><div class="banner"><div class="eyebrow">OFFICE ALL-STARS / 常駐卡池</div><h1>最後一抽。<br><em>下次也是。</em></h1><p>抽到的不是救世主。<br>是可以替你接下一場會議的人。</p><img src="/assets/alice.png" alt="愛麗絲推薦卡池"><div class="banner-badge">65 張卡<br><b>人物 × 物品 × 事件</b></div></div><div class="draw-controls"><div class="eyebrow">PICK YOUR POOL</div><h2>今天想抽到什麼？</h2><div class="pool-options">${[['all','綜合卡池'],['character','只抽人物'],['item','只抽物品'],['event','只抽事件']].map(([value,label])=>`<label><input type="radio" name="banner" value="${value}" ${filter===value?'checked':''} ${busy?'disabled':''}><span>${label}</span></label>`).join('')}</div><div class="pity"><div><span>距離 SSR 保底</span><b>${20-state.drawPity} 抽</b></div><meter min="0" max="20" value="${state.drawPity}" aria-label="SSR 保底累積 ${state.drawPity} / 20"></meter><small>所有卡池共用。抽到 SSR 重新累積；第 20 抽必出 SSR。</small></div><button class="primary draw-button" data-draw="10" ${busy||state.tickets<10||state.battle?.status==='active'?'disabled':''}>十連抽 <span>${icon('ticket',17)} 10</span></button><button class="secondary draw-button" data-draw="1" ${busy||state.tickets<1||state.battle?.status==='active'?'disabled':''}>單抽 <span>${icon('ticket',17)} 1</span></button><p class="guarantee">十連至少一張 R 以上。每抽基礎機率：SSR ${RARITY_ODDS.SSR}%／R ${RARITY_ODDS.R}%／N ${RARITY_ODDS.N}%。同稀有度、同卡池內等機率；保底會提高高稀有度實際比率。</p>${state.battle?.status==='active'?'<button class="text-button" data-tab="campaign">挑戰進行中，先回戰場 →</button>':''}<details class="rules"><summary>重複卡、升級與抽卡券怎麼算？</summary><p>重複 N／R／SSR 卡獲得 2／6／18 碎片。碎片可製作缺少的卡，也能將卡升至 Lv.5。每局人生完成至少 3 個工作回合後，依已驗證的結算積分與工作回合可領 1～12 張券；同一局只能領一次。開場離職不發券。十關挑戰各有一次首勝獎勵，不重複刷券。</p></details></div></section><section class="featured"><div class="section-heading"><div><div class="eyebrow">MEET THE CAST</div><h2>這次，把誰帶進會議室？</h2></div><button class="text-button" data-tab="collection">看完整卡冊 ↗</button></div><div class="featured-cards">${['person-alice','person-jack','item-goose','event-database'].map(id=>cardView(CARD_MAP[id],{small:true})).join('')}</div></section>`;}
function collectionPage(){const cards=CARD_CATALOG.filter(c=>(filter==='all'||c.kind===filter)&&(!ownedOnly||state.collection[c.id]));return`<section class="page-heading"><div class="eyebrow">THE COLLECTION</div><h1>不是每張，都抽得到。<br><em>但每張，都有用。</em></h1><p>點開卡片看技能、升級與製作。未擁有的卡也能用碎片指定製作，沒有抽不到就永遠卡關的門檻。</p></section><div class="collection-filters"><div class="chip-group">${[['all','全部'],['character','人物'],['item','物品'],['event','事件']].map(([v,label])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${label}</button>`).join('')}</div><label class="toggle"><input type="checkbox" data-owned ${ownedOnly?'checked':''}>只看已擁有</label><span>${cards.length} 張</span></div><div class="collection-grid">${cards.map(c=>cardView(c)).join('')}</div>`;}
function deckPage(){if(!deckDraft)deckDraft={characters:[...state.deck],...state.loadout};const owned=CARD_CATALOG.filter(c=>state.collection[c.id]);return`<section class="page-heading"><div class="eyebrow">BUILD YOUR DECK</div><h1>三個人，<em>一場不想輸的會。</em></h1><p>選三位不同人物。物品提供全場被動，事件卡每場只能用一次。補血與護盾能延長戰線，破防讓後段火力更有效。</p><p class="detail-note">變更後請先按「儲存編成」，挑戰會使用已儲存的隊伍。</p></section><div class="deck-layout"><section class="deck-editor"><div class="section-heading"><h2>出勤名單 <small>${deckDraft.characters.length} / 3</small></h2><button class="primary" data-save-deck ${busy||deckDraft.characters.length!==3||state.battle?.status==='active'?'disabled':''}>儲存編成 ${icon('check',17)}</button></div><div class="party-picker">${owned.filter(c=>c.kind==='character').map(c=>`<button class="party-choice ${deckDraft.characters.includes(c.id)?'selected':''}" data-pick-person="${c.id}" aria-pressed="${deckDraft.characters.includes(c.id)}" ${busy||state.battle?.status==='active'?'disabled':''}><img src="${c.portrait}" alt=""><b>${esc(c.name)}</b><span>${c.rarity} · Lv.${state.collection[c.id].level}</span><span class="choice-check">${deckDraft.characters.includes(c.id)?icon('check',15):'＋'}</span></button>`).join('')}</div><div class="loadout"><label>全隊裝備<select data-equip="item" ${busy||state.battle?.status==='active'?'disabled':''}>${owned.filter(c=>c.kind==='item').map(c=>`<option value="${c.id}" ${deckDraft.item===c.id?'selected':''}>${esc(c.name)} · ${c.rarity}</option>`).join('')}</select><small>${esc(CARD_MAP[deckDraft.item]?.description)}</small></label><label>本場事件<select data-equip="event" ${busy||state.battle?.status==='active'?'disabled':''}>${owned.filter(c=>c.kind==='event').map(c=>`<option value="${c.id}" ${deckDraft.event===c.id?'selected':''}>${esc(c.name)} · ${c.rarity}</option>`).join('')}</select><small>${esc(effectText(CARD_MAP[deckDraft.event]))}</small></label></div></section><aside class="strategy-note"><span>${icon('shield',34)}</span><h3>愛麗絲的組隊小抄</h3><p>想穩一點：帶一位補血、一位護盾。<br>打不穿：帶佐證技能或破防物品。<br>第三回合前：先掩護，再接重攻勢。</p><p>技能冷卻是全隊共用的回合進程。這回合換一個人出手，前一位也會慢慢準備好。</p><button class="secondary" data-tab="campaign">查看關卡（先儲存編成） →</button></aside></div>`;}
function campaignPage(){if(state.battle?.status==='active')return battlePage();const last=state.battle;return`${last?`<section class="battle-result ${last.status==='won'?'won':''}" role="status"><div class="eyebrow">${last.status==='won'?'CHALLENGE CLEAR':'BACK TO THE OFFICE'}</div><h2>${last.status==='won'?'這場會，換你說了算。':last.status==='abandoned'?'先收隊，重編再來。':'這次先散會。'}</h2><p>${last.status==='won'?(last.reward?`首勝取得 ${last.reward} 張抽卡券；碎片已放進卡冊。`:'這關首勝獎勵已領過，本次不重複發放。'):'卡片與等級都會保留。調整隊伍、裝備或出手時機後，可以免費重試。'}</p></section>`:''}<section class="page-heading"><div class="eyebrow">OFFICE CAMPAIGN / ${state.campaign.completed.length} OF 10</div><h1>這次開會，<em>讓你出牌。</em></h1><p>關卡不花券。人物生命每場重置，抽卡與升級請在戰鬥之間進行。首勝獎勵只領一次。</p></section><div class="stage-grid">${STAGES.map(stage=>{const complete=state.campaign.completed.includes(stage.id),locked=stage.id>1&&!state.campaign.completed.includes(stage.id-1);return`<article class="stage-card ${complete?'cleared':''} ${locked?'locked':''}"><div class="stage-number">${String(stage.id).padStart(2,'0')} ${complete?icon('check',18):icon('flag',18)}</div><img src="${stage.portrait}" alt="${esc(stage.name)}關卡角色"><h2>${stage.name}</h2><p>${stage.description}</p><span class="stage-stats">生命 ${stage.hp} · 攻擊 ${stage.attack} · 防禦 ${stage.armor}</span><button class="${locked?'secondary':'primary'}" data-stage="${stage.id}" ${busy||locked?'disabled':''}>${locked?'前一關尚未通過':complete?'再次練習':'開始挑戰'}<span>${complete?'已領首勝':`${icon('ticket',15)} 首勝 ${stage.reward}`}</span></button></article>`;}).join('')}</div>`;}
function health(now,max,label){return`<div class="health-line"><meter min="0" max="${max}" value="${now}" aria-label="${esc(label)}生命 ${now} / ${max}"></meter><span>${now} / ${max}</span></div>`;}
function battlePage(){const b=state.battle,stage=STAGES[b.stage-1];if(!b.party[actor]||b.party[actor].hp<=0)actor=b.party.findIndex(p=>p.hp>0);const chosen=b.party[actor],card=CARD_MAP[chosen.id],strong=b.round%3===0,nextTarget=b.party.map((p,i)=>({p,i})).filter(({p})=>p.hp>0);const victim=nextTarget[(b.round-1)%nextTarget.length];return`<section class="battle-heading"><div><div class="eyebrow">STAGE ${String(b.stage).padStart(2,'0')} / TURN ${b.round}</div><h1>${stage.name}</h1></div><button class="text-button danger" data-abandon ${busy?'disabled':''}>先撤退，調整隊伍 ↗</button></section><section class="battlefield"><article class="enemy-panel"><div class="enemy-art"><img src="${stage.portrait}" alt="本關對手"></div><div class="enemy-info"><div class="eyebrow">THE OTHER SIDE</div><h2>${esc(CARD_MAP[`person-${stage.portrait.split('/').pop().split('.')[0]}`]?.name||stage.name)}</h2>${health(b.enemy.hp,b.enemy.maxHp,'對手')}<div class="enemy-stats"><span>防禦 ${b.enemy.armor}</span><span>攻擊 ${b.enemy.attack}</span>${b.enemy.weakenTurns?`<span>削弱 -${b.enemy.weaken} · ${b.enemy.weakenTurns} 次</span>`:''}</div><div class="enemy-intent ${strong?'strong':''}">${icon(strong?'sword':'arrow',19)}<div><b>${strong?'下一步：重攻勢':'下一步：普通反擊'}</b><span>目標 ${esc(CARD_MAP[victim.p.id].name)} · ${Math.max(2,b.enemy.attack+(strong?6:0)-(b.enemy.weakenTurns?b.enemy.weaken:0))} 攻勢${strong?'，可以先掩護。':''}</span></div></div></div></article><div class="versus">OFFICE<br>VS.<br>YOU</div><div class="battle-party">${b.party.map((p,i)=>{const c=CARD_MAP[p.id];return`<button data-actor="${i}" class="fighter ${actor===i?'selected':''} ${p.hp<=0?'down':''}" aria-pressed="${actor===i}" ${busy||p.hp<=0?'disabled':''}><img src="${c.portrait}" alt=""><div><b>${esc(c.name)} <small>Lv.${state.collection[p.id].level}</small></b>${health(p.hp,p.maxHp,c.name)}<span>攻擊 ${p.attack}${p.boost?`＋${p.boost}`:''} · 護盾 ${p.shield} · ${p.cooldown?`技能 ${p.cooldown} 回合`:'技能就緒'}</span></div></button>`;}).join('')}</div></section><section class="battle-action"><div class="selected-skill"><span>本回合由 <b>${esc(card.name)}</b> 出手</span><small>${card.skill}：${card.description}</small></div><div class="move-grid"><button data-move="strike" ${busy?'disabled':''}>${icon('sword')}<strong>普通出手</strong><span>攻擊後由對方反擊</span></button><button data-move="guard" ${busy?'disabled':''}>${icon('shield')}<strong>全隊掩護</strong><span>加護盾，自己恢復 7 生命</span></button><button data-move="skill" ${busy||chosen.cooldown>0?'disabled':''}>${icon('spark')}<strong>${esc(card.skill)}</strong><span>${chosen.cooldown?`還需 ${chosen.cooldown} 回合`:'角色技能 · 冷卻 3 回合'}</span></button><button data-move="event" ${busy||b.eventUsed?'disabled':''}>${icon('cards')}<strong>${esc(CARD_MAP[state.loadout.event].name)}</strong><span>${b.eventUsed?'本場已使用':'事件卡 · 本場限一次'}</span></button></div><p class="event-help">${esc(effectText(CARD_MAP[state.loadout.event]))}</p></section><section class="battle-log" aria-live="polite"><div class="eyebrow">MEETING MINUTES / 最近紀錄</div><ol>${b.log.slice(-7).map(line=>`<li>${esc(line)}</li>`).join('')}</ol></section>`;}
function detailModal(card){const entry=state?.collection[card.id],isBattle=state?.battle?.status==='active';return`<div class="modal-shade"><section class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="card-title"><button class="modal-close" data-close-detail aria-label="關閉卡片">${icon('close')}</button><div>${cardView(card,{selectable:false})}</div><div class="detail-copy"><div class="eyebrow">${card.rarity} / ${CARD_KINDS[card.kind]} / ${entry?`Lv.${entry.level}`:'尚未收藏'}</div><h2 id="card-title">${esc(card.name)}</h2><p class="flavor">${esc(card.kind==='event'?effectText(card):card.flavor)}</p>${card.kind==='character'?`<p class="detail-stats">生命 ${card.hp+(entry?entry.level-1:0)*12} · 攻擊 ${card.attack+(entry?entry.level-1:0)*4}<br><b>${card.skill}</b>：${card.description}</p>`:card.kind==='item'?`<p class="detail-stats">裝備被動：${esc(card.description)}<br>目前強度：${Math.floor(itemPower(card,entry?.level||1))}。升級可加強這件裝備的被動，效果會套用全隊。</p>`:`<p class="detail-stats">本場限一次：${esc(effectText(card))}<br>目前效果強度：${eventPower(card,entry?.level||1)}${card.effect==='charge'?' 點追加傷害（並重置技能冷卻）':'（依上方效果套用）'}。每次升級都會加強這張事件卡。</p>`}${entry?`<p>抽到 ${entry.copies} 次 · 目前 Lv.${entry.level} / 5</p><button class="primary" data-upgrade="${card.id}" ${busy||isBattle||entry.level>=5||state.shards<upgradeCost(entry.level)?'disabled':''}>${entry.level>=5?'已達最高等級':`升到 Lv.${entry.level+1} · ${upgradeCost(entry.level)} 碎片`}</button>`:state?`<button class="primary" data-craft="${card.id}" ${busy||isBattle||state.shards<craftCost(card.rarity)?'disabled':''}>指定製作 · ${craftCost(card.rarity)} 碎片</button>`:''}<p class="detail-note">卡片不會因挑戰失敗而消失。${isBattle?'挑戰進行中，暫時不能升級或製作。':''}</p></div></section></div>`;}
function revealModal(){const cards=reveal.cards;return`<div class="modal-shade reveal-shade"><section class="reveal-modal" role="dialog" aria-modal="true" aria-labelledby="reveal-title"><div class="reveal-heading"><div><div class="eyebrow">${reveal.recovered?'LATEST CONFIRMED DRAW / 最近一次已確認抽卡':'THE RESULTS ARE IN'}</div><h2 id="reveal-title">${cards.some(c=>CARD_MAP[c.id].rarity==='SSR')?'金光來了。先別說最後一抽。':'這次的同事，都到齊了。'}</h2></div><button class="secondary" data-close-reveal>收進卡冊 ${icon('check',17)}</button></div><div class="reveal-grid ${cards.length===1?'single':''}">${cards.map((c,i)=>`<div style="--reveal-index:${i}">${cardView(CARD_MAP[c.id],{selectable:false,drawn:c})}</div>`).join('')}</div><p class="reveal-note">新卡已加入收藏，重複卡的碎片也已入帳。${state.drawPity===0?'SSR 保底重新開始累積。':`再 ${20-state.drawPity} 抽必出 SSR。`}</p></section></div>`;}
function render(){root.innerHTML=shell(!state?intro():tab==='draw'?drawPage():tab==='deck'?deckPage():tab==='campaign'?campaignPage():collectionPage());bind();if(selected||reveal){const dialog=root.querySelector('[role="dialog"]');dialog?.querySelector('button')?.focus({preventScroll:true});}}
async function connect(){if(busy)return;const previous=state,wasPractice=cardClient.mode==='practice';busy=true;error='';render();try{state=await cardClient.connect();notice='卡冊已就緒。正式收藏沿用移動人生的匿名身分。';if(state.lastResult?.type==='draw'&&(!previous||wasPractice||state.totalDraws>previous.totalDraws))reveal={...state.lastResult,recovered:true};deckDraft=null;}catch(e){error=e.message||'卡冊服務暫時無法連線。';}finally{busy=false;render();}}
async function act(action){if(busy||!state)return;busy=true;error='';notice='';render();try{state=await cardClient.action(state,action);if(action.type==='draw')reveal=state.lastResult;if(action.type==='set-deck')notice='出勤名單已更新。';if(action.type==='upgrade')notice=`${CARD_MAP[action.cardId].name}已升至 Lv.${state.collection[action.cardId].level}。`;if(action.type==='craft')notice=`${CARD_MAP[action.cardId].name}加入卡冊。`;if(['set-deck','draw','craft'].includes(action.type))deckDraft=null;if(action.type==='start-battle'||action.type==='abandon-battle'||(action.type==='battle-turn'&&state.battle?.status!=='active'))window.scrollTo({top:0,behavior:'instant'});}catch(e){error=e.message||'操作尚未確認，請重新連線。';}finally{busy=false;render();}}
function chooseTab(next){tab=next;filter='all';selected=null;notice='';error='';render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function bind(){root.querySelectorAll('[data-connect]').forEach(el=>el.onclick=connect);root.querySelector('[data-practice]')?.addEventListener('click',async()=>{state=await cardClient.practice();error='';notice='這是獨立的本機練習卡冊，不會把練習券或卡片同步到正式收藏。';render();});root.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>chooseTab(el.dataset.tab));root.querySelectorAll('input[name="banner"]').forEach(el=>el.onchange=()=>{filter=el.value;});root.querySelectorAll('[data-draw]').forEach(el=>el.onclick=()=>act({type:'draw',count:Number(el.dataset.draw),banner:filter}));root.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render();});root.querySelector('[data-owned]')?.addEventListener('change',e=>{ownedOnly=e.target.checked;render();});root.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>{selected=el.dataset.inspect;render();});root.querySelector('[data-close-detail]')?.addEventListener('click',()=>{selected=null;render();});root.querySelector('[data-close-reveal]')?.addEventListener('click',()=>{reveal=null;render();});root.querySelectorAll('[data-upgrade]').forEach(el=>el.onclick=()=>act({type:'upgrade',cardId:el.dataset.upgrade}));root.querySelectorAll('[data-craft]').forEach(el=>el.onclick=()=>act({type:'craft',cardId:el.dataset.craft}));root.querySelectorAll('[data-pick-person]').forEach(el=>el.onclick=()=>{const id=el.dataset.pickPerson;if(deckDraft.characters.includes(id))deckDraft.characters=deckDraft.characters.filter(c=>c!==id);else if(deckDraft.characters.length<3)deckDraft.characters.push(id);else{notice='隊伍已經有三位，先取消一位再換人。';}render();});root.querySelectorAll('[data-equip]').forEach(el=>el.onchange=()=>{deckDraft[el.dataset.equip]=el.value;render();});root.querySelector('[data-save-deck]')?.addEventListener('click',()=>act({type:'set-deck',...deckDraft}));root.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>act({type:'start-battle',stage:Number(el.dataset.stage)}));root.querySelectorAll('[data-actor]').forEach(el=>el.onclick=()=>{actor=Number(el.dataset.actor);render();});root.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>act({type:'battle-turn',move:el.dataset.move,target:actor}));root.querySelector('[data-abandon]')?.addEventListener('click',()=>{if(confirm('先撤退嗎？卡片不會損失，本次不領首勝獎勵。'))void act({type:'abandon-battle'});});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(selected||reveal)){selected=null;reveal=null;render();}if(e.key==='Tab'&&(selected||reveal)){const dialog=root.querySelector('[role="dialog"]'),focusables=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled)')];if(!focusables.length){e.preventDefault();return;}const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();
